#define spriteWidth 15.
#define spriteDepth 9.
#define frameCount 13.
#define pi 3.1415926535
# define float_max 1e30f

const vec4 blank = vec4(0);
const float stackSpacing = 1.;
const float invFrameCount = 1. / frameCount;
const float invSpriteWidth = 1. / spriteWidth;
const float invSpriteDepth = 1. / spriteDepth;
const float invStackingSpacing = 1. / stackSpacing;
const vec3 backgroundColor = vec3(0.83);

const vec3 position = vec3(-spriteWidth, -frameCount, -spriteDepth) / 2.;
const vec3 dimensions = vec3(spriteWidth, frameCount, spriteDepth) + 2.;
const vec3 rayDir = vec3(0,0,1);

struct Ray
{
    vec3 origin;
    vec3 direction;
};

struct AABB
{
    vec3 _min;
    vec3 _max;
};

AABB get_aabb(vec3 _v1, vec3 _v2)
{
    return AABB(min(_v1, _v2), max(_v1, _v2));
}

float ray_aabb(AABB aabb, Ray ray)
{
    vec3 t1 = (aabb._min - ray.origin) / ray.direction;
    vec3 t2 = (aabb._max - ray.origin) / ray.direction;
    vec3 dmin = min(t1, t2);
    vec3 dmax = max(t1, t2);
    float tmin = max(max(dmin.x, dmin.y), dmin.z);
    float tmax = min(min(dmax.x, dmax.y), dmax.z);

    if (tmax >= tmin) return tmin;
    return float_max;
}

vec4 getTexel(vec3 pos)
{
    float stackLayer = floor((pos.y - position.y + stackSpacing - 1e-6) * invStackingSpacing);

    if (stackLayer < 1. || stackLayer >= frameCount + 1.) return blank;

    float _u = (pos.x - position.x) * invSpriteWidth;
	float _v = (pos.z - position.z) * invSpriteDepth;

    if (_u < 0. || _u > 1. || _v < 0. || _v > 1.) return blank;

    float adjustedV = invFrameCount * (_v - stackLayer) + 1.0;
	return texture(iChannel0, vec2(_u, 1. - adjustedV));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(backgroundColor, 1);
    vec2 angle = (iMouse.xy/iResolution.xy - 0.5) * 2.*pi;
    angle.y *= -1.;

    vec2 cosAngle = cos(angle);
    vec2 sinAngle = sin(angle);

    mat3 yRotTransform = mat3(cosAngle.x, 0., sinAngle.x,
                            0., 1., 0.,
                            -sinAngle.x, 0., cosAngle.x);

    mat3 xRotTransform = mat3(1., 0., 0.,
                            0., cosAngle.y, -sinAngle.y,
                            0, sinAngle.y, cosAngle.y);

    mat3 rotTransform = xRotTransform * yRotTransform;


    float cameraScale = 1./(iResolution.y/(frameCount*2.));

    fragCoord *= cameraScale;

    Ray ray = Ray((vec3(fragCoord - (iResolution.xy*cameraScale)/2., -10000)) * rotTransform, rayDir * rotTransform);
    AABB bounds = get_aabb(position, position + dimensions);

    float entry_t = ray_aabb(bounds, ray);
    if (entry_t == float_max) return;

    vec3 entry_pos = ((ray.origin + ray.direction * (entry_t + 0.0001f)));

    vec3 _step = sign(ray.direction);
    vec3 delta = abs(1./ray.direction);

    vec3 pos = floor(entry_pos);

    vec3 tmax = (pos - entry_pos + max(_step, 0.)) / ray.direction;

    for (int axis = 0; axis < 3; ++axis)
    {
        tmax[axis] = mix(tmax[axis], 0., isinf(tmax[axis]));
    }

    vec4 color;
    for (float i = 0.; i < 128.; ++i)
    {
        color = getTexel(pos);

        if (color != blank) 
        {
            //color -= vec4(vec3(0.0005* i*i), 0);
            fragColor = color;
            return;
        }


        if (tmax.x < tmax.y) 
        {
            if (tmax.x < tmax.z) 
            {
                pos.x += _step.x;
                if (pos.x < bounds._min.x || pos.x >= bounds._max.x) break;
                tmax.x += delta.x;
            } 
            else 
            {
                pos.z += _step.z;
                if (pos.z < bounds._min.z || pos.z >= bounds._max.z) break;
                tmax.z += delta.z;
            }
        } 
        else 
        {
            if (tmax.y < tmax.z) 
            {
                pos.y += _step.y;
                if (pos.y < bounds._min.y || pos.y >= bounds._max.y) break;
                tmax.y += delta.y;
            } 
            else 
            {
                pos.z += _step.z;
                if (pos.z < bounds._min.z || pos.z >= bounds._max.z) break;
                tmax.z += delta.z;
            }
        }

    }
}
